messages.content:
{
  "initiative": "Improve first-contact resolution to 97% in the support organisation",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Baseline assessment and target confirmation",
      "owner_role": "Support Performance Analyst",
      "duration_quarters": 1,
      "deliverable": "Consolidated baseline report, metric definitions, and confirmed 97% target with control thresholds"
    },
    {
      "id": "WP-02",
      "title": "Process redesign and knowledge base consolidation",
      "owner_role": "Process Improvement Lead",
      "duration_quarters": 1,
      "deliverable": "Redesigned first-contact resolution process work package with updated knowledge base and job aids"
    },
    {
      "id": "WP-03",
      "title": "Training, competency verification and tools enablement",
      "owner_role": "Learning and Tools Manager",
      "duration_quarters": 1,
      "deliverable": "Delivered training curriculum, competency assessments, and tool configuration to support the deliverable"
    },
    {
      "id": "WP-04",
      "title": "Pilot deployment and controlled rollout",
      "owner_role": "Support Operations Manager",
      "duration_quarters": 1,
      "deliverable": "Pilot run report, corrective action log for any non-conformance, and approval to proceed to full deployment"
    },
    {
      "id": "WP-05",
      "title": "Monitoring, measurement and continuous control",
      "owner_role": "Quality Assurance Lead",
      "duration_quarters": 1,
      "deliverable": "Ongoing measurement framework, dashboard, escalation paths, and gate review-ready performance pack"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Gate 1 - Readiness to redesign",
      "approver_role": "Head of Support",
      "criteria": "Baseline report accepted, target confirmed, and approved plan for process redesign with identified control points for gate review"
    },
    {
      "gate": "G2",
      "name": "Gate 2 - Pilot authorisation",
      "approver_role": "Operations Director",
      "criteria": "Knowledge base and training materials completed, pilot plan approved, and risk register mitigations in place with sign-off"
    },
    {
      "gate": "G3",
      "name": "Gate 3 - Full deployment approval",
      "approver_role": "Chief Quality Officer",
      "criteria": "Pilot demonstrates improvement toward 97% FCR, no critical non-conformance outstanding, and deployment plan accepted"
    },
    {
      "gate": "G4",
      "name": "Gate 4 - Sustained performance sign-off",
      "approver_role": "Executive Sponsor",
      "criteria": "Sustained 97% first-contact resolution over measurement horizon, audit evidence complete, and formal sign-off obtained"
    }
  ],
  "compliance_notes": [
    "All activities will be documented for audit trail and include control evidence at each gate review",
    "Training records, competency assessments, and updated process documents retained per records retention policy"
  ],
  "risks": [
    {
      "risk": "Inaccurate baseline measurement leading to misaligned target",
      "mitigation": "Use multiple data sources, independent verification and statistical sampling during WP-01; raise deviation register if discrepancies found",
      "severity": "high"
    },
    {
      "risk": "Insufficient adoption of redesigned process causing lower FCR",
      "mitigation": "Mandatory competency verification, hands-on coaching during pilot, and escalation of non-conformance items to G2 approver",
      "severity": "medium"
    },
    {
      "risk": "Tool configuration limitations preventing accurate tracking",
      "mitigation": "Early tool assessment in WP-03, contingency manual logging procedure and procurement pathway if change required",
      "severity": "medium"
    },
    {
      "risk": "Uncontrolled changes during rollout increasing variability",
      "mitigation": "Change control process, limited scope rollout, and gate review sign-off required before each expansion phase",
      "severity": "low"
    }
  ],
  "timeline_horizon": "5 quarters from baseline assessment through sustained performance sign-off"
}

{
  "initiative": "Establish self-serve path to first value within next planning period",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Define scope and success criteria for first-value self-serve",
      "owner_role": "Product Portfolio Lead",
      "duration_quarters": 1,
      "deliverable": "Approved scope document and measurable success criteria for first-value self-serve"
    },
    {
      "id": "WP-02",
      "title": "Design minimal self-serve user journey and controls",
      "owner_role": "UX and Controls Architect",
      "duration_quarters": 1,
      "deliverable": "Design package including flow diagrams, control points and non-conformance detection logic"
    },
    {
      "id": "WP-03",
      "title": "Develop MVP components and integration",
      "owner_role": "Engineering Delivery Manager",
      "duration_quarters": 1,
      "deliverable": "Deployed MVP components enabling first-value transactions on a self-serve path"
    },
    {
      "id": "WP-04",
      "title": "Quality assurance, compliance verification and acceptance",
      "owner_role": "Quality & Compliance Lead",
      "duration_quarters": 1,
      "deliverable": "Test reports, compliance evidence and formal sign-off package for go/no-go"
    },
    {
      "id": "WP-05",
      "title": "Release readiness, training and operational handover",
      "owner_role": "Operations Readiness Manager",
      "duration_quarters": 1,
      "deliverable": "Operational runbook, training materials and documented handover with change control"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Gate 1: Scope and Design Review",
      "approver_role": "Portfolio Governance Chair",
      "criteria": "Approved scope, measurable success criteria, and design package demonstrating required controls and mitigation of deviation paths"
    },
    {
      "gate": "G2",
      "name": "Gate 2: Build and Test Review",
      "approver_role": "Engineering Governance Lead",
      "criteria": "Evidence of completed development, passing test results, traceability to requirements and no unresolved non-conformance items"
    },
    {
      "gate": "G3",
      "name": "Gate 3: Compliance and Acceptance",
      "approver_role": "Head of Quality & Compliance",
      "criteria": "Compliance verification completed, regulatory evidence present, risk acceptance and formal sign-off to proceed to operational release"
    },
    {
      "gate": "G4",
      "name": "Gate 4: Operational Readiness Review",
      "approver_role": "Operations Director",
      "criteria": "Operational runbook in place, training completed, change control entry accepted and go/no-go sign-off for production enablement"
    }
  ],
  "compliance_notes": [
    "All work packages require documented traceability to regulatory requirements and auditable evidence of control implementation",
    "Non-conformance handling procedures must be documented and included in the acceptance deliverable",
    "Any deviation from approved scope must follow formal change control and be recorded for gate review"
  ],
  "risks": [
    {
      "risk": "Ambiguous scope leads to rework and delayed first-value delivery",
      "mitigation": "Enforce strict scope sign-off at Gate 1 with measurable success criteria and review of assumptions",
      "severity": "high"
    },
    {
      "risk": "Insufficient controls result in compliance gaps or non-conformance findings",
      "mitigation": "Embed compliance checks into WP-02 and WP-04 with independent verification and audit trail",
      "severity": "medium"
    },
    {
      "risk": "Operational teams not ready to accept handover causing rollback",
      "mitigation": "Early engagement of Operations in WP-05, mandatory training and readiness criteria in Gate 4",
      "severity": "medium"
    }
  ],
  "timeline_horizon": "One planning period (1 quarter) with gates scheduled at end of each work package for consecutive gate review sign-off"
}

{
  "initiative": "Consolidate customer record systems to a single authoritative system",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Inventory and current-state assessment of customer record systems",
      "owner_role": "Systems Data Lead",
      "duration_quarters": 1,
      "deliverable": "Comprehensive register of all systems holding customer records with data flows, access controls and identified deviations"
    },
    {
      "id": "WP-02",
      "title": "Risk and compliance analysis with target system selection",
      "owner_role": "Compliance & Risk Manager",
      "duration_quarters": 1,
      "deliverable": "Selection rationale and compliance impact assessment declaring the chosen authoritative system and required controls"
    },
    {
      "id": "WP-03",
      "title": "Migration design and non-conformance prevention plan",
      "owner_role": "Data Migration Architect",
      "duration_quarters": 2,
      "deliverable": "Migration design package including mapping, transformation rules, rollback procedures and non-conformance handling process"
    },
    {
      "id": "WP-04",
      "title": "Implementation, data migration and validation",
      "owner_role": "Integration Delivery Manager",
      "duration_quarters": 2,
      "deliverable": "Executed migration to the authoritative system, validation reports, reconciliation deliverable and access control configuration"
    },
    {
      "id": "WP-05",
      "title": "Operational handover and control sign-off",
      "owner_role": "Operations Manager",
      "duration_quarters": 1,
      "deliverable": "Operational runbook, monitoring controls, training materials and formal sign-off confirming single-system operational state"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Gate 1 - Baseline and selection review",
      "approver_role": "Chief Data Officer",
      "criteria": "Accept comprehensive register and selection rationale; confirm no unresolved deviations and compliance impact assessed"
    },
    {
      "gate": "G2",
      "name": "Gate 2 - Migration readiness review",
      "approver_role": "Head of IT Infrastructure",
      "criteria": "Approve migration design, rollback plan and non-conformance handling; confirm technical controls and test plan are in place"
    },
    {
      "gate": "G3",
      "name": "Gate 3 - Post-migration validation review",
      "approver_role": "Quality & Compliance Director",
      "criteria": "Validate reconciliation deliverable, evidence of control implementation and absence of outstanding non-conformance before release to operations"
    },
    {
      "gate": "G4",
      "name": "Gate 4 - Operational sign-off",
      "approver_role": "Chief Operating Officer",
      "criteria": "Formal sign-off on operational runbook, monitoring controls and training completion confirming single authoritative system"
    }
  ],
  "compliance_notes": [
    "All activities must maintain audit trail for data provenance and changes; encryption and access control evidence required for approval",
    "Data retention, consent and regulatory requirements to be validated for the chosen system; any deviation requires documented remediation and sign-off"
  ],
  "risks": [
    {
      "risk": "Data loss or corruption during migration causing customer service impact",
      "mitigation": "Establish staged migration with full backups, reconciliation procedures, rollback plan and pre-production dry-runs; enforce post-migration validation",
      "severity": "high"
    },
    {
      "risk": "Regulatory non-conformance due to incomplete consent or retention metadata",
      "mitigation": "Perform compliance audit early, map consent attributes, remediate gaps prior to migration and include compliance checkpoints in gate reviews",
      "severity": "high"
    },
    {
      "risk": "Insufficient access controls on the target system leading to unauthorized access",
      "mitigation": "Implement role-based access control, multi-factor authentication, and independent control testing before sign-off",
      "severity": "medium"
    },
    {
      "risk": "Operational disruption from delayed training or unclear runbooks",
      "mitigation": "Deliver operations runbook and training ahead of cut-over; require operational sign-off gate and monitored support window",
      "severity": "low"
    }
  ],
  "timeline_horizon": "7 quarters from initiation including assessment, selection, design, migration, validation and operational sign-off"
}

{
  "initiative": "Improve capacity forecast accuracy to enable hiring decisions",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Define forecast requirements and success criteria",
      "owner_role": "Workforce Planning Lead",
      "duration_quarters": 1,
      "deliverable": "Documented forecast requirements, success criteria and control points for gate review sign-off"
    },
    {
      "id": "WP-02",
      "title": "Data quality and source alignment",
      "owner_role": "Data Governance Manager",
      "duration_quarters": 1,
      "deliverable": "Data inventory, remediation plan and evidence of data controls to prevent deviation"
    },
    {
      "id": "WP-03",
      "title": "Model development and validation",
      "owner_role": "Capacity Analytics Lead",
      "duration_quarters": 2,
      "deliverable": "Validated forecasting model, validation report and model non-conformance log"
    },
    {
      "id": "WP-04",
      "title": "Process integration and tooling",
      "owner_role": "Operations Systems Manager",
      "duration_quarters": 1,
      "deliverable": "Integrated forecasting process, tool configuration and operational work package procedures"
    },
    {
      "id": "WP-05",
      "title": "Pilot, review and governance sign-off",
      "owner_role": "Head of Planning",
      "duration_quarters": 1,
      "deliverable": "Pilot results, gate review materials and formal governance sign-off"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Requirements Gate",
      "approver_role": "Director of Workforce Planning",
      "criteria": "Requirements approved, control points defined and documented with no outstanding deviation items"
    },
    {
      "gate": "G2",
      "name": "Data & Model Gate",
      "approver_role": "Head of Data Governance",
      "criteria": "Data quality thresholds met, model validation report accepted and non-conformance actions closed or mitigated"
    },
    {
      "gate": "G3",
      "name": "Operational Readiness Gate",
      "approver_role": "COO",
      "criteria": "Tooling integrated, procedures in place and operational work package demonstration completed"
    },
    {
      "gate": "G4",
      "name": "Final Sign-off Gate",
      "approver_role": "Executive Leadership Committee",
      "criteria": "Pilot performance meets success criteria and executive sign-off on hiring planning use of forecast"
    }
  ],
  "compliance_notes": [
    "Forecasting process will retain audit trail for each work package and gate review",
    "Data handling will comply with internal data governance and regulatory control requirements"
  ],
  "risks": [
    {
      "risk": "Insufficient data quality undermines model accuracy",
      "mitigation": "Implement data remediation plan, enforce data controls and schedule targeted validation; escalate unremediated items at gate review",
      "severity": "high"
    },
    {
      "risk": "Model validation identifies significant non-conformance to requirements",
      "mitigation": "Hold model in validation, document non-conformance, apply corrective actions and require re-validation before proceeding",
      "severity": "medium"
    },
    {
      "risk": "Operational integration delays limit use for hiring cycles",
      "mitigation": "Prioritise minimal viable tool configuration, conduct parallel manual controls and seek expedited governance sign-off",
      "severity": "medium"
    }
  ],
  "timeline_horizon": "6 quarters"
}

{
  "initiative": "Improve review process throughput by 15% without adding headcount",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Process Baseline and Measurement Control",
      "owner_role": "Process Improvement Lead",
      "duration_quarters": 1,
      "deliverable": "Validated baseline report of current review cycle times, metrics definitions, and control plan"
    },
    {
      "id": "WP-02",
      "title": "Targeted Task Rebalancing and Standard Work",
      "owner_role": "Engineering Team Lead",
      "duration_quarters": 1,
      "deliverable": "Standard work package and task rebalancing matrix that reallocates activities to remove single-person constraints"
    },
    {
      "id": "WP-03",
      "title": "Tooling and Automation Enablers",
      "owner_role": "IT Automation Lead",
      "duration_quarters": 2,
      "deliverable": "Configured automation scripts and tool integrations that reduce manual handoffs and accelerate document routing"
    },
    {
      "id": "WP-04",
      "title": "Training, Cross-Qualification and Compliance Checks",
      "owner_role": "Quality Assurance Manager",
      "duration_quarters": 1,
      "deliverable": "Training records, cross-qualification matrix and compliance checklists to ensure coverage without added headcount"
    },
    {
      "id": "WP-05",
      "title": "Pilot, Measure, and Scale with Gate Review",
      "owner_role": "Program Manager",
      "duration_quarters": 1,
      "deliverable": "Pilot results package with measured throughput improvement, deviation log, and scaling plan for enterprise roll-out"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Gate Review - Baseline Approval",
      "approver_role": "Director of Operations",
      "criteria": "Sign-off on validated baseline, measurement control plan, and go/no-go to proceed to task rebalancing"
    },
    {
      "gate": "G2",
      "name": "Gate Review - Solution Approval",
      "approver_role": "VP Engineering",
      "criteria": "Approval of standard work, automation scope, and mitigation plan for non-conformance risks prior to pilot"
    },
    {
      "gate": "G3",
      "name": "Gate Review - Pilot Acceptance",
      "approver_role": "Chief Quality Officer",
      "criteria": "Acceptance of pilot deliverable demonstrating >=15% throughput gain or documented approved deviation and corrective actions"
    },
    {
      "gate": "G4",
      "name": "Gate Review - Rollout Sign-off",
      "approver_role": "Executive Steering Committee",
      "criteria": "Final sign-off on scale plan, updated controls, training completion evidence, and residual risk acceptance"
    }
  ],
  "compliance_notes": [
    "All changes will be documented and traceable per controlled document procedures; deviation records are required for any temporary departures from standard work",
    "Automation implementations must pass security and data integrity controls and be reviewed by Quality prior to deployment"
  ],
  "risks": [
    {
      "risk": "Measured improvement fails to reach 15% due to underestimated manual dependencies",
      "mitigation": "Conduct time-and-motion sampling in WP-01, implement cross-qualification in WP-04, and include contingency tasks in pilot; escalate at gate reviews",
      "severity": "high"
    },
    {
      "risk": "Automation introduces unforeseen data handling non-conformance",
      "mitigation": "Use phased deployment with sandbox testing, data validation scripts, and Quality sign-off before production release",
      "severity": "medium"
    },
    {
      "risk": "Staff resistance to new standard work reduces adherence",
      "mitigation": "Deliver targeted training, assign process champions, and monitor adherence via control charts with corrective action triggers",
      "severity": "medium"
    }
  ],
  "timeline_horizon": "6 quarters"
}

{
  "initiative": "Establish a repeatable engineering-to-operations handoff process to improve readiness, reduce variations, and ensure auditable transfer of responsibilities",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Define handoff standard and acceptance criteria",
      "owner_role": "Process Engineering Lead",
      "duration_quarters": 1,
      "deliverable": "Documented handoff standard including acceptance criteria, control checklist, and permitted deviation log"
    },
    {
      "id": "WP-02",
      "title": "Develop handoff record template and tooling",
      "owner_role": "Systems Engineer",
      "duration_quarters": 1,
      "deliverable": "Validated handoff record template and digital form that captures required deliverables and sign-off fields"
    },
    {
      "id": "WP-03",
      "title": "Pilot handoff on select projects and capture non-conformance cases",
      "owner_role": "Manufacturing Transition Lead",
      "duration_quarters": 2,
      "deliverable": "Pilot report with completed handoff records, logged non-conformance instances, and recommended adjustments"
    },
    {
      "id": "WP-04",
      "title": "Train stakeholders and embed control activities",
      "owner_role": "Operations Training Manager",
      "duration_quarters": 1,
      "deliverable": "Training curriculum, attendance records, and checklist sign-off demonstrating competency in the new work package process"
    },
    {
      "id": "WP-05",
      "title": "Formalize governance and integrate into release processes",
      "owner_role": "Quality & Compliance Manager",
      "duration_quarters": 1,
      "deliverable": "Governance document and process map with gate review criteria, escalation paths, and periodic audit schedule"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Standards Approval",
      "approver_role": "Director of Engineering",
      "criteria": "Approval of handoff standard and acceptance criteria; evidence of control checklist and deviation handling defined"
    },
    {
      "gate": "G2",
      "name": "Pilot Review",
      "approver_role": "VP of Manufacturing",
      "criteria": "Assessment of pilot report showing completed handoff records, recorded non-conformance items, and corrective actions"
    },
    {
      "gate": "G3",
      "name": "Operational Readiness Sign-off",
      "approver_role": "Operations Director",
      "criteria": "Confirmation of training completion, demonstrated competency, and readiness to adopt the new work package process"
    },
    {
      "gate": "G4",
      "name": "Compliance Acceptance",
      "approver_role": "Chief Compliance Officer",
      "criteria": "Verification that governance integrates audit controls, escalation paths, and meets regulatory requirements"
    }
  ],
  "compliance_notes": [
    "Process must produce auditable records at each gate review and retain handoff documents per retention policy",
    "Non-conformance events must be logged and closed with root cause and corrective action traceable to the work package",
    "Any permitted deviation requires documented authorization and a documented control to mitigate impact"
  ],
  "risks": [
    {
      "risk": "Unclear acceptance criteria leading to inconsistent transfers",
      "mitigation": "Define specific, measurable acceptance criteria in WP-01 and require checklist completion at every handoff; severity: high",
      "severity": "high"
    },
    {
      "risk": "Stakeholders do not adopt the new record template",
      "mitigation": "Provide hands-on training in WP-04, mandate template use at G2 pilot, and monitor compliance in audits; severity: medium",
      "severity": "medium"
    },
    {
      "risk": "Undetected non-conformance during pilot",
      "mitigation": "Require explicit non-conformance logging in WP-03 with immediate corrective action and review at G2; severity: medium",
      "severity": "medium"
    },
    {
      "risk": "Governance gaps lead to regulatory findings",
      "mitigation": "Engage Quality & Compliance Manager in WP-05 to integrate audit controls and obtain CCO acceptance at G4; severity: high",
      "severity": "high"
    }
  ],
  "timeline_horizon": "6 quarters"
}

{
  "initiative": "Reduce new hire time-to-productivity by 50% through structured onboarding and controlled knowledge transfer",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Onboarding Process Assessment and Baseline",
      "owner_role": "HR Process Lead",
      "duration_quarters": 1,
      "deliverable": "Documented baseline time-to-productivity metrics, gap analysis and list of high-priority process deviations"
    },
    {
      "id": "WP-02",
      "title": "Structured Training Curriculum and Materials",
      "owner_role": "Learning & Development Manager",
      "duration_quarters": 1,
      "deliverable": "Approved modular training curriculum, standard operating procedures and training deliverable kits for new hires"
    },
    {
      "id": "WP-03",
      "title": "Mentor Program and Knowledge Transfer Controls",
      "owner_role": "Operations Training Lead",
      "duration_quarters": 1,
      "deliverable": "Mentor assignment protocol, mentor sign-off checklist and control measures to validate competency transfer"
    },
    {
      "id": "WP-04",
      "title": "Measurement, Reporting and Continuous Improvement",
      "owner_role": "Business Performance Analyst",
      "duration_quarters": 1,
      "deliverable": "Reporting dashboard, success criteria, gate review metrics and plan for corrective actions for any non-conformance"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Gate 1 - Baseline Approval",
      "approver_role": "HR Director",
      "criteria": "Acceptance of baseline metrics, gap analysis and authorization to proceed with development of training deliverables"
    },
    {
      "gate": "G2",
      "name": "Gate 2 - Curriculum and Controls Sign-off",
      "approver_role": "Chief Operating Officer",
      "criteria": "Sign-off on curriculum, mentor protocol and control measures; evidence of pilot training session outcomes"
    },
    {
      "gate": "G3",
      "name": "Gate 3 - Pilot Completion and Rollout Approval",
      "approver_role": "Quality & Compliance Manager",
      "criteria": "Demonstrated 25% reduction in time-to-productivity in pilot, closure of critical deviations and acceptance of measurement plan"
    },
    {
      "gate": "G4",
      "name": "Gate 4 - Full Deployment Authorization",
      "approver_role": "Executive Steering Committee",
      "criteria": "Verified achievement of 50% reduction target in representative cohorts, approved budget for enterprise rollout and residual risk sign-off"
    }
  ],
  "compliance_notes": [
    "All materials and training controls will be documented and retained for audit trail in accordance with corporate record retention policy",
    "Pilot and rollout activities will include documented gate review sign-off and corrective action records for any deviation"
  ],
  "risks": [
    {
      "risk": "Insufficient accuracy of baseline metrics leads to unrealistic targets",
      "mitigation": "Use multiple data sources, validate baseline with sample audits and include conservative confidence intervals",
      "severity": "high"
    },
    {
      "risk": "Inadequate mentor availability delays competency transfer",
      "mitigation": "Define mentor capacity in resource plan, cross-train backup mentors and include mentor workload controls",
      "severity": "medium"
    },
    {
      "risk": "Training content not aligned with operational realities causing non-conformance",
      "mitigation": "Pilot modules in live environment, collect operational feedback, and require sign-off from frontline supervisors prior to rollout",
      "severity": "medium"
    }
  ],
  "timeline_horizon": "12 quarters with phased pilots in first 3 quarters and enterprise rollout over the remaining horizon"
}

{
  "initiative": "Customer Incident Reduction Program: 10% decrease in reported incidents within 12 months",
  "work_packages": [
    {
      "id": "WP-01",
      "title": "Incident Data Consolidation and Baseline Establishment",
      "owner_role": "Quality Data Analyst",
      "duration_quarters": 1,
      "deliverable": "Validated incident baseline report and data control register to support subsequent work packages"
    },
    {
      "id": "WP-02",
      "title": "Root Cause Analysis and Non-conformance Mapping",
      "owner_role": "Continuous Improvement Engineer",
      "duration_quarters": 1,
      "deliverable": "Root cause catalogue and non-conformance mapping with prioritized corrective actions"
    },
    {
      "id": "WP-03",
      "title": "Corrective Action Implementation and Process Controls",
      "owner_role": "Manufacturing Process Manager",
      "duration_quarters": 2,
      "deliverable": "Implemented control measures and documented process changes with evidence of reduced incident frequency"
    },
    {
      "id": "WP-04",
      "title": "Training, Communication and Change Sign-off",
      "owner_role": "Training and Compliance Lead",
      "duration_quarters": 1,
      "deliverable": "Training completion records, communication pack, and formal sign-off of procedural updates"
    },
    {
