    },
    {
      "id": "WP-03",
      "title": "Reliability-Focused Cost Reduction Pilots",
      "owner_role": "Service Reliability Lead",
      "duration_quarters": 2,
      "deliverable": "Pilot results from three major accounts demonstrating >=30% cost reduction target pathways with measured reliability metrics and gate review data"
