    {
      "id": "WP-05",
      "title": "Scale-up and Change Management",
      "owner_role": "Change Management Director",
      "duration_quarters": 2,
      "deliverable": "Rollout plan, training sign-off, risk register updates and non-conformance handling procedures to scale validated approaches across all large accounts"
    }
  ],
  "approval_chain": [
    {
      "gate": "G1",
      "name": "Diagnostic Gate Review",
      "approver_role": "Head of Commercial Operations",
      "criteria": "Accept baseline report with validated cost drivers, documented control points and approval to proceed to pilots; no outstanding critical deviations"
    },
    {
      "gate": "G2",
      "name": "Pilot Approval Gate",
      "approver_role": "VP Service Delivery",
      "criteria": "Approve pilot designs and metrics; require sign-off on reliability thresholds and contingency plans for non-conformance handling"
    },
    {
      "gate": "G3",
      "name": "Scale-up Gate Review",
      "approver_role": "Chief Operating Officer",
      "criteria": "Approve scale-up when pilot results demonstrate sustained >=30% cost reduction for target accounts with no material reliability degradation and updated controls"
    },
    {
      "gate": "G4",
      "name": "Closure and Audit Gate",
      "approver_role": "Head of Compliance and Audit",
      "criteria": "Final sign-off confirming documentation, change records, training sign-offs, and that control evidence meets regulatory and internal audit standards"
    }
  ],
  "compliance_notes": [
    "Maintain auditable trace of decisions at each gate review and retain baseline and pilot datasets for regulatory review",
    "Ensure changes comply with existing service-level agreements and safety regulations; document any deviation with root cause and corrective action",
    "Non-conformance procedures must be active during pilots and scale-up with immediate escalation to the gate approver if safety or contractual reliability thresholds are breached"
  ],
  "risks": [
    {
      "risk": "Cost reduction measures inadvertently degrade reliability leading to contract penalties",
      "mitigation": "Require reliability thresholds in pilot acceptance criteria, deploy monitoring dashboards and rapid rollback controls; escalate to VP Service Delivery on deviation",
      "severity": "high"
    },
    {
      "risk": "Data quality issues undermine baseline and pilot conclusions",
      "mitigation": "Perform data validation in WP-01, include sampling audits and control logs; withhold scale-up approval until data integrity sign-off",
      "severity": "medium"
    },
    {
      "risk": "Operational resistance to standardisation delaying rollout",
      "mitigation": "Early engagement, formal training sign-off, and inclusion of change champions in WP-05 to reduce deviation and enable smoother gate review approvals",
      "severity": "medium"
    }
  ],
  "timeline_horizon": "6 quarters"
}

