  "approval_chain": [
    {
      "gate": "G1",
      "name": "Gate 1 - Baseline Review",
      "approver_role": "Head of Support",
      "criteria": "Review and sign-off of baseline report and measurement control plan; confirm identified deviations and authorise process redesign"
    },
    {
      "gate": "G2",
      "name": "Gate 2 - Pilot Authorisation",
      "approver_role": "Operations Director",
      "criteria": "Approval of redesigned process, training materials and tooling; formal sign-off to commence pilot with agreed success criteria"
    },
    {
      "gate": "G3",
      "name": "Gate 3 - Scale Decision",
      "approver_role": "VP of Service Delivery",
      "criteria": "Pilot performance meets success threshold towards 97% first-contact resolution, remediation of non-conformance items, and acceptance of scale-up plan"
    },
    {
      "gate": "G4",
      "name": "Gate 4 - Closure and Control Handover",
      "approver_role": "Quality Assurance Director",
      "criteria": "Final sign-off on deliverables, handover of control documents and closure of open deviations with documented mitigation"
    }
  ],
  "compliance_notes": [
    "All activities will be executed under existing regulatory frameworks with documented control records and audit trail",
    "Training records, change approvals and sign-off artefacts will be retained for compliance and future gate review evidence"
  ],
