    {
      "risk": "Insufficient data quality undermines measurement of first-contact resolution",
      "mitigation": "Implement immediate data validation routines, reconcile records during WP-01 and include control limits in deliverable",
      "severity": "high"
    },
    {
      "risk": "Agents do not adopt new standard work, causing reversion and non-conformance",
      "mitigation": "Mandatory training, competency sign-off, coaching during pilot and performance-linked reinforcement overseen in WP-03 and WP-04",
      "severity": "medium"
    },
    {
      "risk": "Tooling configuration delays impede pilot schedule",
      "mitigation": "Prioritise critical tool changes in scope, maintain contingency manual steps in pilot and escalate via gate review if required",
      "severity": "medium"
    },
    {
